import{_ as t,c as o,o as a,ae as r}from"./chunks/framework.CliRSA9F.js";const s="/images/signup.webp",n="/images/select_your_podcast.webp",i="/images/onboarding_distribution.webp",d="/images/onboarding_visibility.webp",l="/images/onboarding_keywords.webp",c="/images/add_podcast_sidebar.webp",w=JSON.parse('{"title":"Getting Started with Podseo","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/first-steps.md","filePath":"getting-started/first-steps.md"}'),p={name:"getting-started/first-steps.md"};function h(u,e,g,y,m,f){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="getting-started-with-podseo" tabindex="-1">Getting Started with Podseo <a class="header-anchor" href="#getting-started-with-podseo" aria-label="Permalink to &quot;Getting Started with Podseo&quot;">​</a></h1><p>Welcome to Podseo, your go-to platform for podcast competitive intelligence and SEO insights! This guide will help you quickly set up and start analyzing your podcast&#39;s performance.</p><hr><h3 id="_1-create-an-account" tabindex="-1">1. <strong>Create an Account</strong> <a class="header-anchor" href="#_1-create-an-account" aria-label="Permalink to &quot;1. **Create an Account**&quot;">​</a></h3><p>To access Podseo features:</p><ul><li><p>Visit our <a href="https://podseo.com/accounts/signup/" target="_blank" rel="noreferrer">signup page</a>.</p></li><li><p>Enter your email address and accept the terms, or choose <strong>Sign up with Google</strong>.</p></li></ul><p><img src="'+s+'" alt="Signup Screenshot" width="250px" style="display:block;margin:0 auto;"></p><p>Already have an account? <a href="https://podseo.com/accounts/login/" target="_blank" rel="noreferrer">Log in</a> with a sign-in code sent to your email, your password, or Google.</p><hr><h3 id="_2-add-your-podcast" tabindex="-1">2. <strong>Add Your Podcast</strong> <a class="header-anchor" href="#_2-add-your-podcast" aria-label="Permalink to &quot;2. **Add Your Podcast**&quot;">​</a></h3><p>After logging in, you&#39;ll see the &quot;Select Your Podcast&quot; screen. Click <strong>Find Your Podcast</strong> to search for your show.</p><p><img src="'+n+'" alt="Select Your Podcast" width="500px" style="display:block;margin:0 auto;"></p><p>Search using your podcast&#39;s name, its Apple Podcasts or Spotify link, or its RSS feed URL, then select it from the results. PodSEO finds shows through their Apple Podcasts listing, so make sure your show is listed there. Not launched yet? See <a href="/getting-started/pre-launch-planning.html">Pre-launch Planning</a> (ready soon).</p><h3 id="_3-complete-the-onboarding-wizard" tabindex="-1">3. <strong>Complete the Onboarding Wizard</strong> <a class="header-anchor" href="#_3-complete-the-onboarding-wizard" aria-label="Permalink to &quot;3. **Complete the Onboarding Wizard**&quot;">​</a></h3><p>Once you select your podcast, PodSEO walks you through a guided setup with three steps:</p><p><strong>Distribution</strong> — PodSEO connects your RSS feed and checks your presence across Apple Podcasts, Spotify, Amazon Music, and YouTube Music. You&#39;ll see which platforms found your show and can continue while checks finish in the background.</p><p><img src="'+i+'" alt="Onboarding Distribution" width="500px" style="display:block;margin:0 auto;"></p><p><strong>Visibility</strong> — Your initial Visibility Score is calculated, giving you a baseline of how discoverable your podcast is across platforms.</p><p><img src="'+d+'" alt="Onboarding Visibility" width="500px" style="display:block;margin:0 auto;"></p><p><strong>Keywords</strong> — PodSEO suggests initial keywords based on your podcast&#39;s content. You can review and adjust these to start building your keyword strategy.</p><p><img src="'+l+'" alt="Onboarding Keywords" width="500px" style="display:block;margin:0 auto;"></p><p>After the Keywords step, you land in the <strong>Command Center</strong> — your home base in PodSEO.</p><p>Your plan includes a set number of podcasts (Producer includes 5 and Agency 15). On any paid plan you can also buy extra podcasts with <strong>Add extra podcasts</strong> in Settings → Account; see <a href="/features/billing-and-account.html">Billing and Account Settings</a>. Use the podcast selector at the top of the sidebar to switch between podcasts, and choose <strong>Manage podcasts</strong> there to add or remove podcasts in Settings → Podcasts.</p><p>Keyword rankings are collected as a listener in the United States would see them. If your audience is mainly elsewhere, paid plans let you add search countries per podcast under <strong>Settings → Podcasts</strong>; see <a href="/features/keyword-tracker.html#search-countries">Keyword Tracker</a> for details.</p><p><img src="'+c+'" alt="Add Additional Podcasts" width="500px" style="display:block;margin:0 auto;"></p><hr><h3 id="_4-connect-your-analytics" tabindex="-1">4. <strong>Connect Your Analytics</strong> <a class="header-anchor" href="#_4-connect-your-analytics" aria-label="Permalink to &quot;4. **Connect Your Analytics**&quot;">​</a></h3><p>Bring your listening numbers into PodSEO so you can see them next to your rankings. Click <strong>Analytics</strong> in the sidebar and connect the sources you use: Spotify for Creators, Apple Podcasts Connect, YouTube, your host (Spreaker or Buzzsprout today), OP3, or PodSEO&#39;s own hopr.fm download prefix. Every connection is free on every plan, and each tab walks you through the setup step by step. See <a href="/features/analytics-connections.html">Analytics Connections</a>.</p><hr><h3 id="_5-explore-key-features" tabindex="-1">5. <strong>Explore Key Features</strong> <a class="header-anchor" href="#_5-explore-key-features" aria-label="Permalink to &quot;5. **Explore Key Features**&quot;">​</a></h3><p>Once setup is complete, PodSEO opens to the sidebar navigation where all features are organized in a flat, easy-to-browse layout. Start with the Command Center and explore from there:</p><ul><li><p><strong><a href="/features/command-center.html">Command Center</a></strong> — Your dashboard home showing health signals, tasks, and insights. Start here every session.</p></li><li><p><strong><a href="/features/planner.html">Planner</a></strong> — Plan episodes, check metadata/keyword alignment, and get AI-powered optimization suggestions. Access from Command Center.</p></li><li><p><strong><a href="/features/keyword-strategy.html">Keyword Strategy</a></strong> — Define your SEO strategy with Primary, Secondary, and Monitored keywords. Found under Search Visibility.</p></li><li><p><strong><a href="/features/show-visibility.html">Show Visibility</a></strong> &amp; <strong><a href="/features/episode-visibility.html">Episode Visibility</a></strong> — See where your podcast and individual episodes rank for keywords across platforms. Found under Search Visibility.</p></li><li><p><strong><a href="/features/ai-mentions.html">AI Mentions</a></strong> — Track how often AI platforms like ChatGPT, Claude, Perplexity, and Gemini recommend your podcast. Found under AI Visibility.</p></li><li><p><strong><a href="/features/competitive-analysis.html">Competitive Analysis</a></strong> — Compare your podcast with competitors. Found under Competition.</p></li><li><p><strong><a href="/features/lucia-ai-assistant.html">LUCIA AI Chat</a></strong> — Chat with your personal SEO expert. Access via Chat in the sidebar.</p></li></ul><hr><h3 id="_6-need-help" tabindex="-1">6. <strong>Need Help?</strong> <a class="header-anchor" href="#_6-need-help" aria-label="Permalink to &quot;6. **Need Help?**&quot;">​</a></h3><ul><li><p>Browse our Help Center for tutorials and FAQs, including our <a href="/getting-started/workflow.html">detailed keyword workflow guide</a>.</p></li><li><p>Learn more about <a href="/getting-started/visibility-score-explained.html">how the Visibility Score works</a>.</p></li><li><p>Contact support via <a href="https://podseo.com/settings/contact" target="_blank" rel="noreferrer">Settings → Contact Us</a>.</p></li><li><p>Something not working? See <a href="/more/troubleshooting.html">Troubleshooting</a>.</p></li></ul><hr><p>Start optimizing your podcast&#39;s SEO today with Podseo. For detailed guides and advanced tips, check out our comprehensive feature documentation and academy resources.</p><p>Not live yet? Pre-launch planning is ready soon; see <a href="/getting-started/pre-launch-planning.html">Pre-launch Planning</a>. Working with colleagues or clients? Set up <a href="/features/teams-and-organizations.html">Teams and Organizations</a>, then explore the <a href="/features/agency-workspace.html">Agency workspace</a> on the Agency plan.</p>',38)])])}const k=t(p,[["render",h]]);export{w as __pageData,k as default};
